cat > /tmp/test_json_theme.go << 'EOF'
package main

import (
	"fmt"
	"fyne.io/fyne/v2/theme"
)

func main() {
	// Test FromJSON
	json := `{"Colors": {"button": "#abc"}}`
	th, err := theme.FromJSON(json)
	fmt.Printf("FromJSON result: theme=%v, err=%v\n", th != nil, err)

	// Test invalid JSON returns default theme
	badJson := "not valid json"
	th2, err2 := theme.FromJSON(badJson)
	fmt.Printf("Bad JSON: theme=%v, err=%v\n", th2 != nil, err2 != nil)
}
EOF
GOOS=linux go build -tags ci -o /tmp/test_json_theme /tmp/test_json_theme.go 2>&1 | head -20

cat > /tmp/test_validation.go << 'EOF'
package main

import (
	"fmt"
	"errors"
	"fyne.io/fyne/v2/data/validation"
)

func main() {
	// Test NewAllStrings
	v1 := func(s string) error {
		if len(s) < 3 {
			return errors.New("too short")
		}
		return nil
	}
	v2 := func(s string) error {
		if s != "test" {
			return errors.New("must be 'test'")
		}
		return nil
	}

	combined := validation.NewAllStrings(v1, v2)

	// Should fail on first validator
	err1 := combined("ab")
	fmt.Printf("Short string error: %v\n", err1)

	// Should fail on second validator
	err2 := combined("hello")
	fmt.Printf("Wrong string error: %v\n", err2)

	// Should pass
	err3 := combined("test")
	fmt.Printf("Valid string error: %v\n", err3)
}
EOF
GOOS=linux go build -tags ci -o /tmp/test_validation /tmp/test_validation.go 2>&1

